<section class="container page-heading"><span class="section-kicker">Ruang kerja fotografer</span><h1>Jadwal tugas saya</h1><p>Daftar ini hanya berisi reservasi yang ditugaskan kepada akun Anda. Perbarui status sesi dan unggah hasil foto dari kartu tugas terkait.</p></section>
<section class="container pb-5"><div class="row g-4"><?php foreach($tasks as $task): ?><div class="col-lg-6"><article class="surface surface-pad h-100"><div class="page-toolbar mb-3"><div><span class="section-kicker"><?= e($task['kode_reservasi']) ?></span><h2 class="h4 mt-2 mb-1"><?= e($task['nama_paket']) ?></h2><p class="muted mb-0"><?= e($task['nama_pelanggan']) ?> · <?= e($task['telepon_pelanggan'] ?: 'Tanpa nomor telepon') ?></p></div><span class="badge-status <?= e(status_class($task['status'])) ?>"><?= e(status_label($task['status'])) ?></span></div><div class="detail-grid mb-3"><div class="detail-item"><small>Tanggal</small><strong><?= e(date_id($task['tanggal_sesi'])) ?></strong></div><div class="detail-item"><small>Waktu / durasi</small><strong><?= e(substr((string)$task['jam_sesi'],0,5)) ?> · <?= (int)$task['durasi_menit_snapshot'] ?> menit</strong></div></div><div class="small-actions mb-3"><?php if($task['status']==='dikonfirmasi'): ?><form method="post" action="<?= e(url('photographer-status')) ?>"><?= csrf_field() ?><input type="hidden" name="id_reservasi" value="<?= (int)$task['id_reservasi'] ?>"><button class="btn btn-copper btn-sm" type="submit" name="action" value="mulai">Mulai Pemotretan</button></form><?php elseif($task['status']==='sedang_foto'): ?><form method="post" action="<?= e(url('photographer-status')) ?>"><?= csrf_field() ?><input type="hidden" name="id_reservasi" value="<?= (int)$task['id_reservasi'] ?>"><button class="btn btn-copper btn-sm" type="submit" name="action" value="selesai" data-confirm="Tandai sesi ini selesai?">Tandai Selesai</button></form><?php else: ?><span class="badge-status success">Sesi selesai</span><?php endif; ?></div><hr style="border-color:var(--line)"><h3 class="h6 mb-3">Unggah hasil foto</h3><form method="post" enctype="multipart/form-data" action="<?= e(url('photographer-upload')) ?>"><?= csrf_field() ?><input type="hidden" name="id_reservasi" value="<?= (int)$task['id_reservasi'] ?>"><div class="mb-3"><input class="form-control" type="file" name="foto" accept="image/jpeg,image/png,image/webp" required><div class="form-note mt-2">JPG, PNG, atau WebP. Maksimal <?= (int)$GLOBALS['config']['upload_max_mb'] ?> MB per file.</div></div><button class="btn btn-outline-dark btn-sm" type="submit">Unggah Foto Privat ↗</button></form></article></div><?php endforeach; ?><?php if(!$tasks): ?><div class="col-12"><div class="empty-state"><div class="empty-symbol">◷</div><h2 style="font:500 1.8rem Georgia,serif">Belum ada tugas terjadwal</h2><p>Tugas muncul setelah admin mengonfirmasi pembayaran dan menugaskan Anda ke reservasi.</p></div></div><?php endif; ?></div></section>
